@tool
extends EditorPlugin

var browser: Node
var report: Dictionary = {}

func find_browser(node: Node) -> void:
    var script: Script = node.get_script()
    if script != null and script.resource_path == "res://addons/assets2godot/plugin.gd":
        browser = node
        return
    for child in node.get_children():
        find_browser(child)

func _enter_tree() -> void:
    if DisplayServer.get_name() == "headless":
        return
    run_check.call_deferred()

func fetch_json(url: String) -> Variant:
    var req := HTTPRequest.new()
    req.timeout = 25.0
    add_child(req)
    var err := req.request(url, ["User-Agent: Assets2Godot/0.8.2 integration check"])
    if err != OK:
        req.queue_free()
        return null
    var response: Array = await req.request_completed
    req.queue_free()
    if response[0] != HTTPRequest.RESULT_SUCCESS or response[1] != 200:
        return null
    return JSON.parse_string(response[3].get_string_from_utf8())

func run_check() -> void:
    await get_tree().create_timer(12.0).timeout
    find_browser(get_tree().root)
    if browser == null:
        finish(false)
        return
    EditorInterface.set_main_screen_editor("A2G")
    browser.set_client_enabled(true)
    report["enable_request_blocked"] = not browser.client_enabled and int(browser.connection.state) == 0
    report["client_enabled"] = browser.client_enabled
    report["client_state"] = int(browser.connection.state)
    report["blendkit_visible"] = browser.provider_enabled("blendkit")
    report["providers"] = {}
    for key in ["polyhaven", "ambientcg"]:
        var pane: Node = browser._provider_panes[key]
        report.providers[key] = {"catalog_state": pane.catalog_state, "assets": pane._assets.size(), "resolution": pane._res_hint}
    var api = load("res://addons/assets2godot/a2g/polyhaven_api.gd")
    var pane: Node = browser._provider_panes.polyhaven
    for spec in [{"slug":"metal_jerrycan_green", "type":"model", "format":"gltf"}, {"slug":"wood_planks_grey", "type":"texture", "format":"jpg"}]:
        var files: Variant = await fetch_json(api.files_url(spec.slug))
        var options: Array = api.flatten_files(files)
        var picked: Dictionary = {}
        for option in options:
            if str(option.get("key", "")).contains("1k") and str(option.get("key", "")).contains(spec.format):
                picked = option
                break
        if picked.is_empty():
            report[spec.slug] = {"error":"No matching 1K option", "keys":options.map(func(x): return x.get("key", ""))}
            continue
        pane._start_download({"slug":spec.slug,"type":spec.type,"name":spec.slug}, picked)
        var deadline := Time.get_ticks_msec() + 120000
        while (pane._dl_req != null or pane._converting) and Time.get_ticks_msec() < deadline:
            await get_tree().create_timer(0.2).timeout
        report[spec.slug] = {"downloaded":pane._dl_done.has(spec.slug), "status":pane._status.text, "option":picked.get("key", "")}
    finish(not browser.client_enabled and not browser.provider_enabled("blendkit"))

func finish(ok: bool) -> void:
    report["policy_ok"] = ok
    var file := FileAccess.open("res://probe_result.json", FileAccess.WRITE)
    file.store_string(JSON.stringify(report, "  "))
    file.close()
    print("TEST: isolated editor probe ", JSON.stringify(report))
    get_tree().quit(0 if ok else 1)

